 p_id=>wwv_flow_imp.id(9226508227629340)
,p_name=>unistr('Prioridade de Investiga\00E7\00E3o por Hospital')
,p_static_id=>unistr('hospitais-que-exigem-aten\00E7\00E3o')
,p_template=>4073835273271169698
,p_display_sequence=>70
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    AP_NOME_HOSPITAL AS HOSPITAL,',
'    COUNT(*) AS ATENDIMENTOS,',
'    ROUND(AVG(AP_DTAUT - AP_DTSOLIC), 1) AS TEMPO_MEDIO_AUTORIZACAO,',
'',
'    CASE',
'        WHEN AVG(AP_DTAUT - AP_DTSOLIC) >= 20 THEN',
'            ''<span class="t-Badge t-Badge--danger">Alta</span>''',
'        WHEN AVG(AP_DTAUT - AP_DTSOLIC) >= 5 THEN',
unistr('            ''<span class="t-Badge t-Badge--warning">M\00E9dia</span>'''),
'        ELSE',
'            ''<span class="t-Badge t-Badge--success">Baixa</span>''',
'    END AS NIVEL_ATENCAO',
'',
'FROM ADMIN.BARI',
'',
'WHERE AP_DTAUT IS NOT NULL',
'  AND AP_DTSOLIC IS NOT NULL',
'',
'GROUP BY AP_NOME_HOSPITAL',
'',
'ORDER BY',
'    CASE',
'        WHEN AVG(AP_DTAUT - AP_DTSOLIC) >= 20 THEN 1',
'        WHEN AVG(AP_DTAUT - AP_DTSOLIC) >= 5 THEN 2',
'        ELSE 3',
'    END,',
'    AVG(AP_DTAUT - AP_DTSOLIC) DESC'))
