,p_plug_display_sequence=>30
,p_plug_new_grid_row=>false
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    ''Total de Atendimentos'' AS INDICADOR,',
'    TO_CHAR(COUNT(*)) AS VALOR,',
'    1 AS ORDEM',
'FROM ADMIN.BARI',
'WHERE (',
'    :P2_HOSPITAL IS NULL',
'    OR AP_NOME_HOSPITAL = :P2_HOSPITAL',
')',
'',
'UNION ALL',
'',
'SELECT',
'    ''Hospitais Analisados'',',
'    TO_CHAR(COUNT(DISTINCT AP_NOME_HOSPITAL)),',
'    2',
'FROM ADMIN.BARI',
'WHERE (',
'    :P2_HOSPITAL IS NULL',
'    OR AP_NOME_HOSPITAL = :P2_HOSPITAL',
')',
'',
'UNION ALL',
'',
'SELECT',
unistr('    ''Tempo M\00E9dio de Autoriza\00E7\00E3o'','),
'    TO_CHAR(',
'        ROUND(',
'            AVG(AP_DTAUT - AP_DTSOLIC),',
'            1',
'        )',
'    ) || '' dias'',',
'    3',
'FROM ADMIN.BARI',
'WHERE AP_DTAUT IS NOT NULL',
'  AND AP_DTSOLIC IS NOT NULL',
'  AND (',
'      :P2_HOSPITAL IS NULL',
'      OR AP_NOME_HOSPITAL = :P2_HOSPITAL',
'  )',
'',
'UNION ALL',
'',
'SELECT',
'    ''Altas Registradas'',',
'    TO_CHAR(SUM(AP_ALTA)),',
'    4',
'FROM ADMIN.BARI',
'WHERE (',
'    :P2_HOSPITAL IS NULL',
'    OR AP_NOME_HOSPITAL = :P2_HOSPITAL',
')'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
