,p_plug_name=>unistr('An\00E1lise Hospitalar')
,p_static_id=>unistr('an\00E1lise-hospitalar')
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    AP_NOME_HOSPITAL AS HOSPITAL,',
'',
'    APEX_PAGE.GET_URL(',
'        p_page        => 5,',
'        p_clear_cache => ''5'',',
'        p_items       => ''P5_HOSPITAL'',',
'        p_values      => AP_NOME_HOSPITAL',
'    ) AS DETALHE_URL,',
'',
'    COUNT(*) AS TOTAL_ATENDIMENTOS,',
'',
'    ROUND(AVG(AP_NUIDADE), 1) AS IDADE_MEDIA,',
'',
'    ROUND(',
'        AVG(',
'            CASE',
'                WHEN AP_DTAUT IS NOT NULL',
'                 AND AP_DTSOLIC IS NOT NULL',
'                THEN AP_DTAUT - AP_DTSOLIC',
'            END',
'        ),',
'        1',
'    ) AS TEMPO_MEDIO_AUTORIZACAO,',
'',
'    SUM(AP_ALTA) AS ALTAS,',
'    SUM(AP_PERMAN) AS PERMANENCIAS',
'',
'FROM ADMIN.BARI',
'',
'GROUP BY AP_NOME_HOSPITAL',
'',
'ORDER BY TOTAL_ATENDIMENTOS DESC'))
