,p_plug_name=>'Indicadores do Hospital'
,p_static_id=>'indicadores-do-hospital'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2074200852440250129
,p_plug_display_sequence=>40
,p_plug_new_grid_row=>false
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    ''Atendimentos'' AS INDICADOR,',
'    TO_CHAR(COUNT(*)) AS VALOR,',
'    1 AS ORDEM',
'FROM ADMIN.BARI',
'WHERE AP_NOME_HOSPITAL = :P5_HOSPITAL',
'',
'UNION ALL',
'',
'SELECT',
unistr('    ''Idade M\00E9dia'' AS INDICADOR,'),
'    TO_CHAR(ROUND(AVG(AP_NUIDADE), 1)) || '' anos'' AS VALOR,',
'    2 AS ORDEM',
'FROM ADMIN.BARI',
'WHERE AP_NOME_HOSPITAL = :P5_HOSPITAL',
'',
'UNION ALL',
'',
'SELECT',
unistr('    ''Tempo M\00E9dio de Autoriza\00E7\00E3o'' AS INDICADOR,'),
'    TO_CHAR(',
'        ROUND(',
'            AVG(AP_DTAUT - AP_DTSOLIC),',
'            1',
'        )',
'    ) || '' dias'' AS VALOR,',
'    3 AS ORDEM',
'FROM ADMIN.BARI',
'WHERE AP_NOME_HOSPITAL = :P5_HOSPITAL',
'  AND AP_DTAUT IS NOT NULL',
'  AND AP_DTSOLIC IS NOT NULL',
'',
'UNION ALL',
'',
'SELECT',
'    ''Altas'' AS INDICADOR,',
'    TO_CHAR(SUM(AP_ALTA)) AS VALOR,',
'    4 AS ORDEM',
'FROM ADMIN.BARI',
'WHERE AP_NOME_HOSPITAL = :P5_HOSPITAL'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
